// Family and timetable operations shared by the VPS and hosted API.
export function parentsFor(s){const parents=Array.isArray(s.parents)?s.parents:[],seen=new Set(parents.map(p=>p.family));return [...parents,...s.children.filter(c=>{if(seen.has(c.family))return false;seen.add(c.family);return true}).map(c=>({id:'parent-'+c.family,family:c.family,name:c.parent,phone:c.phone||'',email:c.email||'',archived:!!c.archived}))]}
export function familyCanEnter(s,family,created=Infinity){return s.children.some(c=>c.family===family&&!c.archived)&&parentsFor(s).some(p=>p.family===family&&!p.archived)&&created>(s.familyAccessRevokedAt?.[family]||0)}
const starts=l=>new Date(l.date+'T'+l.time+':00+05:00');
const text=(v,max=100)=>String(v||'').trim().slice(0,max);
export function applyManagement(s,a,actor,now=new Date()){
 const types=['parent','parent-update','parent-archive','parent-restore','child-update','child-archive','child-restore','lesson-update','lesson-cancel','booking-move'];if(!types.includes(a.type))return false;
 const master=()=>{if(actor.role!=='master')throw Error('Только для мастера')};if(a.type!=='booking-move')master();s.parents=parentsFor(s);
 const log=t=>s.activity.unshift({text:t,time:now.toLocaleTimeString('ru-RU',{hour:'2-digit',minute:'2-digit',timeZone:'Asia/Yekaterinburg'}),type:a.type});
 const revoke=family=>{s.familyAccessRevokedAt||={};s.familyAccessRevokedAt[family]=Math.max(now.getTime(),(s.familyAccessRevokedAt[family]||0)+1)};
 const sync=family=>{const p=s.parents.find(p=>p.family===family&&!p.archived);for(const c of s.children.filter(c=>c.family===family)){c.parent=p?.name||'Родитель не указан';c.phone=p?.phone||'';c.email=p?.email||''}};
 if(a.type.startsWith('parent')){s.parents=parentsFor(s);let p=s.parents.find(p=>p.id===a.parent);
  if(a.type==='parent'){const name=text(a.name),phone=text(a.phone,30),email=text(a.email,254);if(!name||(!phone&&!email)||email&&!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email))throw Error('Укажите имя родителя и телефон или корректную почту');if(a.family&&!s.children.some(c=>c.family===a.family)&&!s.parents.some(p=>p.family===a.family))throw Error('Семья не найдена');p={id:crypto.randomUUID(),family:a.family||crypto.randomUUID(),name,phone,email,archived:false};s.parents.push(p)}
  else{if(!p)throw Error('Родитель не найден');if(a.type==='parent-update'){const name=text(a.name),phone=text(a.phone,30),email=text(a.email,254);if(!name||(!phone&&!email)||email&&!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email))throw Error('Укажите имя родителя и контакты');Object.assign(p,{name,phone,email})}else if(a.type==='parent-archive'&&!p.archived){p.archived=true;revoke(p.family)}else if(a.type==='parent-restore')p.archived=false}
  sync(p.family);log(p.name+(p.archived?' — родитель убран в архив':' — данные родителя сохранены'));return true;
 }
 if(a.type.startsWith('child-')){const c=s.children.find(c=>c.id===a.child);if(!c)throw Error('Ребёнок не найден');
  if(a.type==='child-update'){if(!text(a.name)||!Number.isInteger(+a.age)||+a.age<3||+a.age>18)throw Error('Укажите имя и возраст от 3 до 18 лет');c.name=text(a.name);c.age=+a.age}
  if(a.type==='child-archive'&&!c.archived){c.archived=true;for(const b of s.bookings.filter(b=>b.child===c.id&&['booked','waitlist'].includes(b.status)))if(starts(s.lessons.find(l=>l.id===b.lesson))>now)b.status='cancelled';if(!s.children.some(x=>x.family===c.family&&!x.archived))revoke(c.family)}
  if(a.type==='child-restore')c.archived=false;log(c.name+(c.archived?' — ребёнок убран в архив':' — данные ребёнка сохранены'));return true;
 }
 if(a.type==='booking-move'){const b=s.bookings.find(b=>b.id===a.booking),c=s.children.find(c=>c.id===b?.child&&!c.archived),from=s.lessons.find(l=>l.id===b?.lesson),to=s.lessons.find(l=>l.id===a.lesson);if(!b||!c||actor.role!=='master'&&c.family!==actor.family)throw Error('Запись не найдена');if(!['booked','waitlist'].includes(b.status)||!from||from.status==='cancelled'||starts(from)<=now)throw Error('Перенести можно только предстоящую запись');if(actor.role!=='master'&&(starts(from)-now)/36e5<s.settings.cancelHours)throw Error('До занятия меньше '+s.settings.cancelHours+' ч. Свяжитесь с мастером');if(!to||to.status==='cancelled'||starts(to)<=now||to.id===from.id)throw Error('Выберите другое предстоящее занятие');if(s.bookings.some(x=>x.id!==b.id&&x.child===c.id&&x.lesson===to.id&&x.status!=='cancelled'))throw Error('Ребёнок уже записан на выбранное занятие');if(s.bookings.filter(x=>x.lesson===to.id&&!['cancelled','waitlist'].includes(x.status)).length>=to.capacity)throw Error('На выбранном занятии нет свободных мест');b.movedFrom=from.id;b.lesson=to.id;b.status='booked';log(c.name+' — запись перенесена на '+to.date+' '+to.time);return true}
 const l=s.lessons.find(l=>l.id===a.lesson);if(!l||l.status==='cancelled')throw Error('Занятие недоступно');if(starts(l)<=now)throw Error('Изменять расписание можно только для предстоящего занятия');if(s.bookings.some(b=>b.lesson===l.id&&['attended','missed'].includes(b.status)))throw Error('Сначала снимите отметки посещения в журнале');
 const oldDate=l.date,oldTime=l.time,ids=s.bookings.filter(b=>b.lesson===l.id&&['booked','waitlist'].includes(b.status)).map(b=>b.child);
 if(a.type==='lesson-cancel'){l.status='cancelled';l.cancellationReason=text(a.reason,500);for(const b of s.bookings.filter(b=>b.lesson===l.id&&['booked','waitlist'].includes(b.status))){b.status='cancelled';b.cancellationReason=l.cancellationReason||'Занятие отменено мастером'}}else{const date=text(a.date),time=text(a.time),duration=+a.duration;if(!/^\d{4}-\d{2}-\d{2}$/.test(date)||!/^([01]\d|2[0-3]):[0-5]\d$/.test(time)||!Number.isInteger(duration)||duration<1||duration>1440)throw Error('Проверьте дату, время и длительность');const target=new Date(date+'T'+time+':00+05:00');if(!Number.isFinite(+target)||target<=now||target.toLocaleDateString('sv-SE',{timeZone:'Asia/Yekaterinburg'})!==date)throw Error('Укажите корректную будущую дату');Object.assign(l,{date,time,duration})}
 s.lessonUpdates||=[];s.lessonUpdates.unshift({id:crypto.randomUUID(),lesson:l.id,title:l.title,kind:a.type==='lesson-cancel'?'cancelled':'moved',oldDate,oldTime,date:l.date,time:l.time,reason:text(a.reason,500),children:ids});s.lessonUpdates=s.lessonUpdates.slice(0,2000);log('Занятие «'+l.title+'» '+(l.status==='cancelled'?'отменено':'перенесено'));return true;
}
